  #[allow(unused_mut)]
  pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
    _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
    args: &'args SKTArgs<'args>
  ) -> ::flatbuffers::WIPOffset<SKT<'bldr>> {
    let mut builder = SKTBuilder::new(_fbb);
    builder.add_PAYLOAD_BYTES(args.PAYLOAD_BYTES);
    builder.add_STRETCH_SOFTENING(args.STRETCH_SOFTENING);
    builder.add_WHITE_POINT(args.WHITE_POINT);
    builder.add_BLACK_POINT(args.BLACK_POINT);
    builder.add_MAP_OFFSET(args.MAP_OFFSET);
    builder.add_MAP_SCALE(args.MAP_SCALE);
    builder.add_EPOCH(args.EPOCH);
    builder.add_WAVELENGTH_MAX_NM(args.WAVELENGTH_MAX_NM);
    builder.add_WAVELENGTH_MIN_NM(args.WAVELENGTH_MIN_NM);
    builder.add_WAVELENGTH_EFF_NM(args.WAVELENGTH_EFF_NM);
    builder.add_PIXEL(args.PIXEL);
    if let Some(x) = args.LICENSE_URL { builder.add_LICENSE_URL(x); }
    if let Some(x) = args.CITATION { builder.add_CITATION(x); }
    if let Some(x) = args.PRODUCED_AT { builder.add_PRODUCED_AT(x); }
    if let Some(x) = args.PRODUCER_VERSION { builder.add_PRODUCER_VERSION(x); }
    if let Some(x) = args.PRODUCER_PEER_ID { builder.add_PRODUCER_PEER_ID(x); }
    if let Some(x) = args.SOURCE_NAMES { builder.add_SOURCE_NAMES(x); }
    if let Some(x) = args.OBSERVATION_END { builder.add_OBSERVATION_END(x); }
    if let Some(x) = args.OBSERVATION_START { builder.add_OBSERVATION_START(x); }
    if let Some(x) = args.PAYLOAD_CID { builder.add_PAYLOAD_CID(x); }
    if let Some(x) = args.PERCENTILE_VALUES { builder.add_PERCENTILE_VALUES(x); }
    if let Some(x) = args.PERCENTILE_LEVELS { builder.add_PERCENTILE_LEVELS(x); }
    if let Some(x) = args.MAP_VALUES { builder.add_MAP_VALUES(x); }
    builder.add_MAP_BLANK(args.MAP_BLANK);
    if let Some(x) = args.MAP_UNITS { builder.add_MAP_UNITS(x); }
    if let Some(x) = args.MAP_QUANTITY_NAME { builder.add_MAP_QUANTITY_NAME(x); }
    if let Some(x) = args.ROW_COLLECTION_CID { builder.add_ROW_COLLECTION_CID(x); }
    if let Some(x) = args.POINTS { builder.add_POINTS(x); }
    if let Some(x) = args.COLOR_RED_BAND_ID { builder.add_COLOR_RED_BAND_ID(x); }
    if let Some(x) = args.COLOR_BLUE_BAND_ID { builder.add_COLOR_BLUE_BAND_ID(x); }
    builder.add_MAG_LIMIT(args.MAG_LIMIT);
    builder.add_MAG_BRIGHTEST(args.MAG_BRIGHTEST);
    builder.add_POINT_COUNT(args.POINT_COUNT);
    if let Some(x) = args.OBSERVER_ID { builder.add_OBSERVER_ID(x); }
    if let Some(x) = args.BAND_ID { builder.add_BAND_ID(x); }
    if let Some(x) = args.LAYER_ID { builder.add_LAYER_ID(x); }
    builder.add_STRETCH(args.STRETCH);
    builder.add_MAP_QUANTITY(args.MAP_QUANTITY);
    builder.add_MAP_ENCODING(args.MAP_ENCODING);
    builder.add_MAP_DEPTH(args.MAP_DEPTH);
    builder.add_COLOR_ENCODING(args.COLOR_ENCODING);
    builder.add_PLACE(args.PLACE);
    builder.add_MAGNITUDE_SYSTEM(args.MAGNITUDE_SYSTEM);
    builder.add_SPECTRAL_REGIME(args.SPECTRAL_REGIME);
    builder.add_REFINE(args.REFINE);
    builder.add_PAYLOAD_KIND(args.PAYLOAD_KIND);
    builder.add_CHILD_MASK(args.CHILD_MASK);
    builder.add_MAX_ORDER(args.MAX_ORDER);
    builder.add_ORDER(args.ORDER);
    builder.add_FRAME(args.FRAME);
    builder.finish()
  }

  pub fn unpack(&self) -> SKTT {
    let LAYER_ID = {
      let x = self.LAYER_ID();
      alloc::string::ToString::to_string(x)
    };
    let FRAME = self.FRAME();
    let ORDER = self.ORDER();
    let PIXEL = self.PIXEL();
    let MAX_ORDER = self.MAX_ORDER();
    let CHILD_MASK = self.CHILD_MASK();
    let PAYLOAD_KIND = self.PAYLOAD_KIND();
    let REFINE = self.REFINE();
    let SPECTRAL_REGIME = self.SPECTRAL_REGIME();
    let BAND_ID = self.BAND_ID().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let WAVELENGTH_EFF_NM = self.WAVELENGTH_EFF_NM();
    let WAVELENGTH_MIN_NM = self.WAVELENGTH_MIN_NM();
    let WAVELENGTH_MAX_NM = self.WAVELENGTH_MAX_NM();
    let MAGNITUDE_SYSTEM = self.MAGNITUDE_SYSTEM();
    let PLACE = self.PLACE();
    let EPOCH = self.EPOCH();
    let OBSERVER_ID = self.OBSERVER_ID().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let POINT_COUNT = self.POINT_COUNT();
    let MAG_BRIGHTEST = self.MAG_BRIGHTEST();
    let MAG_LIMIT = self.MAG_LIMIT();
    let COLOR_ENCODING = self.COLOR_ENCODING();
    let COLOR_BLUE_BAND_ID = self.COLOR_BLUE_BAND_ID().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let COLOR_RED_BAND_ID = self.COLOR_RED_BAND_ID().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let POINTS = self.POINTS().map(|x| {
      x.iter().map(|t| t.unpack()).collect()
    });
    let ROW_COLLECTION_CID = self.ROW_COLLECTION_CID().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let MAP_DEPTH = self.MAP_DEPTH();
    let MAP_ENCODING = self.MAP_ENCODING();
    let MAP_QUANTITY = self.MAP_QUANTITY();
    let MAP_QUANTITY_NAME = self.MAP_QUANTITY_NAME().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let MAP_UNITS = self.MAP_UNITS().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let MAP_SCALE = self.MAP_SCALE();
    let MAP_OFFSET = self.MAP_OFFSET();
    let MAP_BLANK = self.MAP_BLANK();
    let MAP_VALUES = self.MAP_VALUES().map(|x| {
      x.into_iter().collect()
    });
    let STRETCH = self.STRETCH();
    let BLACK_POINT = self.BLACK_POINT();
    let WHITE_POINT = self.WHITE_POINT();
    let STRETCH_SOFTENING = self.STRETCH_SOFTENING();
    let PERCENTILE_LEVELS = self.PERCENTILE_LEVELS().map(|x| {
      x.into_iter().collect()
    });
    let PERCENTILE_VALUES = self.PERCENTILE_VALUES().map(|x| {
      x.into_iter().collect()
    });
    let PAYLOAD_CID = self.PAYLOAD_CID().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let PAYLOAD_BYTES = self.PAYLOAD_BYTES();
    let OBSERVATION_START = self.OBSERVATION_START().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let OBSERVATION_END = self.OBSERVATION_END().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let SOURCE_NAMES = self.SOURCE_NAMES().map(|x| {
      x.iter().map(|s| alloc::string::ToString::to_string(s)).collect()
    });
    let PRODUCER_PEER_ID = self.PRODUCER_PEER_ID().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let PRODUCER_VERSION = self.PRODUCER_VERSION().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let PRODUCED_AT = self.PRODUCED_AT().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let CITATION = self.CITATION().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let LICENSE_URL = self.LICENSE_URL().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    SKTT {
      LAYER_ID,
      FRAME,
      ORDER,
      PIXEL,
      MAX_ORDER,
      CHILD_MASK,
      PAYLOAD_KIND,
      REFINE,
      SPECTRAL_REGIME,
      BAND_ID,
      WAVELENGTH_EFF_NM,
      WAVELENGTH_MIN_NM,
      WAVELENGTH_MAX_NM,
      MAGNITUDE_SYSTEM,
      PLACE,
      EPOCH,
      OBSERVER_ID,
      POINT_COUNT,
      MAG_BRIGHTEST,
      MAG_LIMIT,
      COLOR_ENCODING,
      COLOR_BLUE_BAND_ID,
      COLOR_RED_BAND_ID,
      POINTS,
      ROW_COLLECTION_CID,
      MAP_DEPTH,
      MAP_ENCODING,
      MAP_QUANTITY,
      MAP_QUANTITY_NAME,
      MAP_UNITS,
      MAP_SCALE,
      MAP_OFFSET,
      MAP_BLANK,
      MAP_VALUES,
      STRETCH,
      BLACK_POINT,
      WHITE_POINT,
      STRETCH_SOFTENING,
      PERCENTILE_LEVELS,
      PERCENTILE_VALUES,
      PAYLOAD_CID,
      PAYLOAD_BYTES,
      OBSERVATION_START,
      OBSERVATION_END,
      SOURCE_NAMES,
      PRODUCER_PEER_ID,
      PRODUCER_VERSION,
      PRODUCED_AT,
      CITATION,
      LICENSE_URL,
    }
  }

